def min_spanning_tree(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str, int]]:
    # Store original index to preserve input order in the result
    indexed_roads = []
    for i, (a, b, km) in enumerate(edges):
        if a == b:
            continue
        u, v = sorted((a, b))
        indexed_roads.append((km, u, v, i))

    parent: Dict[str, str] = {}

    def find(code: str) -> str:
        parent.setdefault(code, code)
        while parent[code] != code:
            parent[code] = parent[parent[code]]
            code = parent[code]
        return code

    chosen_indices = []
    # Sort by weight, then by normalized nodes for tie-breaking
    for km, u, v, idx in sorted(indexed_roads):
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            parent[root_u] = root_v
            chosen_indices.append(idx)

    # Return edges in the order they appeared in the original input
    # We need the original (a, b, km) tuples
    original_edges = list(edges)
    return [original_edges[i] for i in sorted(chosen_indices)]
