import heapq
from typing import List, Mapping, Optional, Tuple


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits:
        raise KeyError(src)
    if dst not in limits:
        raise KeyError(dst)
    if src == dst:
        raise ValueError("src and dst cannot be the same")

    INF_LOAD = 10**18
    start_path = (src,)
    heap: List[Tuple[int, int, Tuple[str, ...]]] = [(-INF_LOAD, 0, start_path)]
    best = {src: (-INF_LOAD, 0, start_path)}

    while heap:
        neg_load, legs, path = heapq.heappop(heap)
        current = path[-1]
        current_load = -neg_load

        if current == dst:
            return (current_load, list(path))

        if best.get(current) < (neg_load, legs, path):
            continue

        neighbors = limits.get(current, {})
        for neighbor in sorted(neighbors.keys()):
            weight = neighbors[neighbor]
            new_load = min(current_load, weight)
            new_legs = legs + 1
            new_path = path + (neighbor,)
            candidate = (-new_load, new_legs, new_path)

            if neighbor not in best or candidate < best[neighbor]:
                best[neighbor] = candidate
                heapq.heappush(heap, candidate)

    return None
